    """Split xs into consecutive chunks of length k; the last chunk may be shorter."""
    if k <= 0:
        raise ValueError("k must be positive")
    return [xs[i:i + k] for i in range(0, len(xs), k)]

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def days_between(a: str, b: str) -> int:
    """Number of days from ISO date a to ISO date b (b - a)."""
    from datetime import date
    try:
        d1 = date.fromisoformat(a)
        d2 = date.fromisoformat(b)
    except ValueError as e:
        raise ValueError(f"Invalid ISO date format: {e}")
    return (d2 - d1).days

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            # ignore non‑bracket characters
            continue
    return not stack

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v):
        try:
            major, minor, patch = (int(part) for part in v.split('.'))
        except Exception:
            # fallback: treat non-numeric parts as zero
            parts = v.split('.')
            major = int(parts[0]) if parts[0].isdigit() else 0
            minor = int(parts[1]) if len(parts)>1 and parts[1].isdigit() else 0
            patch = int(parts[2]) if len(parts)>2 and parts[2].isdigit() else 0
        return major, minor, patch
    return sorted(vs, key=key)

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    result = {}
    for token in text.split():
        # strip punctuation from both ends
        word = token.strip('.,!?')
        if not word:
            continue
        word = word.lower()
        result[word] = result.get(word, 0) + 1
    return result
